def present(name, auth=None, **kwargs):
    """
    Ensure image exists and is up-to-date

    name
        Name of the image

    enabled
        Boolean to control if image is enabled

    description
        An arbitrary description of the image
    """
    ret = {"name": name, "changes": {}, "result": True, "comment": ""}

    if auth:
        kwargs["auth"] = auth

    if __salt__["glance.image_exists"](name, **kwargs):
        image = __salt__["glance.image_show"](name, **kwargs)
        if image["enabled"] != kwargs.get("enabled", True):
            if __opts__["test"]:
                ret["comment"] = "Image {} is set to be enabled.".format(name)
                ret["changes"]["enabled"] = kwargs.get("enabled", True)
                ret["result"] = None
            else:
                __salt__["glance.image_modify"](name, enabled=kwargs.get("enabled", True), **kwargs)
                ret["comment"] = "Image {} is enabled.".format(name)
                ret["changes"]["enabled"] = kwargs.get("enabled", True)
        if image["description"] != kwargs.get("description", None):
            if __opts__["test"]:
                ret["comment"] = "Image {} is set to have description '{}'.".format(name, kwargs.get("description", None))
                ret["changes"]["description"] = kwargs.get("description", None)
                ret["result"] = None
            else:
                __salt__["glance.image_modify"](name, description=kwargs.get("description", None), **kwargs)
                ret["comment"] = "Image {} has description '{}'.".format(name, kwargs.get("description", None))
                ret["changes"]["description"] = kwargs.get("description", None)
        if image["container_format"] != kwargs.get("container_format", None):
            if __opts__["test"]:
                ret["comment"] = "Image {} is set to have container_format '{}'.".format(
                    name, kwargs.get("container_format", None)
                )
                ret["changes"]["container_format"] = kwargs.get("container_format", None)
                ret["result"] = None
            else:
